with
hub_fund_source as (
    select distinct
        vehicle_fund_business_key
    from {{ ref("investment__legal_vehicle_vault__base") }}
    where vehicle_fund_business_key is not null
),
hub_fund_keyed as (
    select
        {{ dpf_vault_hash(["vehicle_fund_business_key"]) }} as fund_hk,
        vehicle_fund_business_key,
        {{ dpf_publish_timestamp() }} as load_datetime,
        'investment.legal_vehicle_vault' as record_source
    from hub_fund_source
),
hub_fund_unstored as (
    select
        fund_hk,
        vehicle_fund_business_key,
        load_datetime,
        record_source
    from hub_fund_keyed
    where {{ dpf_vault_unstored_key("hub_fund_keyed", "fund_hk") }}
)

select
    cast(fund_hk as {{ dpf_type('string') }}) as fund_hk,
    cast(vehicle_fund_business_key as {{ dpf_type('string') }}) as vehicle_fund_business_key,
    cast(load_datetime as {{ dpf_type('timestamp') }}) as load_datetime,
    cast(record_source as {{ dpf_type('string') }}) as record_source
from hub_fund_unstored
